-- A23: cliente comprador em rascunho; reutiliza Party e papel temporal, sem documento, contato, lote vendido, contrato, boleto ou financeiro.
create table public.subdivision_buyer_clients (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,party_role_assignment_id uuid not null,created_by uuid not null references public.identity_subjects(user_id) on delete restrict,created_at timestamptz not null default now(),constraint subdivision_buyer_clients_role_fk foreign key(party_role_assignment_id,organization_id) references public.party_role_assignments(id,organization_id) on delete restrict,constraint subdivision_buyer_clients_unique unique(organization_id,party_role_assignment_id));
alter table public.subdivision_buyer_clients enable row level security;revoke all on table public.subdivision_buyer_clients from public,anon,authenticated;
comment on table public.subdivision_buyer_clients is 'A23: cliente comprador interno em rascunho por Party/papel temporal; sem documentos, contato, identificadores fiscais, lote vendido, contrato, boleto ou financeiro.';
create or replace function public.subdivision_create_draft_buyer_client(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text,p_party_role_assignment_id uuid,p_correlation_id uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare v_existing uuid;v_id uuid;begin perform private.require_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code);select target_id into v_existing from public.admin_audit_events where command_name='subdivision_create_draft_buyer_client' and correlation_id=p_correlation_id and outcome='allowed' order by occurred_at desc limit 1;if v_existing is not null then return v_existing;end if;if not exists(select 1 from public.party_role_assignments where id=p_party_role_assignment_id and organization_id=p_organization_id and module='loteadora' and role in ('client','buyer') and state='draft')then raise exception using errcode='42501',message='SUBDIVISION_BUYER_CLIENT_CONTEXT_DENIED';end if;insert into public.subdivision_buyer_clients(organization_id,party_role_assignment_id,created_by)values(p_organization_id,p_party_role_assignment_id,p_actor_user_id)on conflict(organization_id,party_role_assignment_id)do update set created_by=excluded.created_by returning id into v_id;insert into public.admin_audit_events(correlation_id,actor_user_id,organization_id,command_name,outcome,target_type,target_id,payload_redacted)values(p_correlation_id,p_actor_user_id,p_organization_id,'subdivision_create_draft_buyer_client','allowed','subdivision_buyer_client',v_id,jsonb_build_object('module',p_module::text,'purpose_code',trim(p_purpose_code),'buyer_client_linked',true));return v_id;end;$$;
revoke all on function public.subdivision_create_draft_buyer_client(uuid,uuid,public.operating_module,text,uuid,uuid) from public,anon,authenticated;grant execute on function public.subdivision_create_draft_buyer_client(uuid,uuid,public.operating_module,text,uuid,uuid) to service_role;
create or replace function public.subdivision_list_draft_buyer_clients(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text) returns table(buyer_client_id uuid,party_role_assignment_id uuid,created_at timestamptz) language plpgsql security definer set search_path='' as $$ begin perform private.require_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code);return query select id,party_role_assignment_id,created_at from public.subdivision_buyer_clients where organization_id=p_organization_id order by created_at desc;end;$$;revoke all on function public.subdivision_list_draft_buyer_clients(uuid,uuid,public.operating_module,text) from public,anon,authenticated;grant execute on function public.subdivision_list_draft_buyer_clients(uuid,uuid,public.operating_module,text) to service_role;
